"""Elastic channel for streaming data ingestion into Snowflake tables."""

from __future__ import annotations

import logging
from concurrent.futures import Future
from http import HTTPStatus
from typing import Any, Dict, List

import msgspec

from snowflake.ingest.streaming._python_ffi import (
    PyBinaryInputFormat,
)
from snowflake.ingest.streaming._python_ffi import (
    PyChannel as _StreamingIngestChannel,
)
from snowflake.ingest.streaming._utils import (
    _rethrow_ffi_errors,
    convert_bytes_in_row,
)
from snowflake.ingest.streaming.channel_status import ChannelStatus
from snowflake.ingest.streaming.streaming_ingest_error import (
    StreamingIngestError,
    StreamingIngestErrorCode,
)

logger = logging.getLogger(__name__)


class StreamingIngestElasticChannel:
    """Elastic channel for Snowflake Streaming Ingest.

    Unlike regular channels, elastic channels have no offset token concepts and
    their lifecycle is tied to the client (no close method). The same instance is
    returned on repeated calls to
    :meth:`~snowflake.ingest.streaming.streaming_ingest_client.StreamingIngestClient.get_elastic_channel`.

    Note:
        This class should not be instantiated directly. Use
        :meth:`~snowflake.ingest.streaming.streaming_ingest_client.StreamingIngestClient.get_elastic_channel`
        to obtain the elastic channel instance.
    """

    @_rethrow_ffi_errors
    def __init__(
        self,
        channel: _StreamingIngestChannel,
        pending_futures: Dict[int, Future],
        *,
        binary_input_format: PyBinaryInputFormat,
        _internal: bool = False,
    ):
        """Initialize a StreamingIngestElasticChannel instance.

        Args:
            channel: The underlying Rust channel instance.
            pending_futures: Map of pending Future IDs to their Futures.
            binary_input_format: Encoding format for binary column values.
            _internal: Must be True; prevents direct instantiation.

        Raises:
            ValueError: If instantiated directly without _internal=True.
        """
        if not _internal:
            raise ValueError(
                "StreamingIngestElasticChannel cannot be instantiated directly. "
                "Use StreamingIngestClient.get_elastic_channel() instead."
            )
        self._channel = channel
        self._pending_futures = pending_futures
        self._serializer = msgspec.json.Encoder()
        if not isinstance(binary_input_format, PyBinaryInputFormat):
            raise TypeError(
                f"binary_input_format must be a PyBinaryInputFormat enum, got {type(binary_input_format)}"
            )
        self._binary_input_format = binary_input_format

    def append_row(self, row: Dict[str, Any]) -> Future:
        """Append a single row into the elastic channel.

        Args:
            row: Dictionary representing the row data to append.

        Returns:
            Future: Completes when the row is acknowledged by Snowflake.

        Raises:
            ValueError, TypeError: If the row cannot be serialized to JSON.
            StreamingIngestError: If the row appending fails.
        """
        if row is None:
            raise ValueError("row must not be None")
        return self.append_rows([row])

    @_rethrow_ffi_errors
    def append_rows(self, rows: List[Dict[str, Any]]) -> Future:
        """Append multiple rows into the elastic channel.

        Args:
            rows: List of dictionaries representing the row data to append.

        Returns:
            Future: Completes when the rows are acknowledged by Snowflake.

        Raises:
            ValueError, TypeError: If the rows cannot be serialized to JSON.
            StreamingIngestError: If the rows appending fails.
        """
        if rows is None:
            raise ValueError("rows must not be None")
        try:
            if self._binary_input_format != PyBinaryInputFormat.BASE64:
                rows = [
                    convert_bytes_in_row(row, self._binary_input_format) for row in rows
                ]
            json_bytes = self._serializer.encode_lines(rows)
        except Exception as e:
            raise ValueError(f"Failed to serialize rows to JSON: {e}") from e

        future_id = self._channel.append_rows(json_bytes, len(rows), True, None, None)

        future = Future()
        previous = self._pending_futures.get(future_id, None)
        self._pending_futures[future_id] = future
        if previous is not None:
            error_msg = f"Duplicate future_id={future_id} in pendingFutures"
            error = StreamingIngestError(
                StreamingIngestErrorCode.FATAL,
                error_msg,
                HTTPStatus.INTERNAL_SERVER_ERROR.value,
                HTTPStatus.INTERNAL_SERVER_ERROR.phrase,
            )
            if not previous.done():
                previous.set_exception(error)
            else:
                logger.warning(
                    "Duplicate future_id=%d already completed for channel=%s",
                    future_id,
                    self._channel.channel_name,
                )
            self._channel.invalidate_channel(error_msg)
            raise error

        return future

    @_rethrow_ffi_errors
    def initiate_flush(self) -> None:
        """Initiate a flush of all buffered data in this channel without waiting for completion.

        Raises:
            StreamingIngestError: If initiating the flush fails.
        """
        self._channel.initiate_flush()

    @_rethrow_ffi_errors
    def get_channel_status(self) -> ChannelStatus:
        """Get the status of the elastic channel.

        Returns:
            ChannelStatus: The status of the channel.

        Raises:
            StreamingIngestError: If getting the channel status fails.
        """
        status = self._channel.get_channel_status()
        return ChannelStatus.from_py_status(status)

    def is_closed(self) -> bool:
        """Check if the elastic channel is closed (because the client was closed).

        Returns:
            bool: True if the channel is closed, False otherwise.
        """
        return self._channel.is_closed()

    @property
    def channel_name(self) -> str:
        """Get the channel name (always "ELASTIC")."""
        return self._channel.channel_name

    @property
    def db_name(self) -> str:
        """Get the database name."""
        return self._channel.db_name

    @property
    def schema_name(self) -> str:
        """Get the schema name."""
        return self._channel.schema_name

    @property
    def pipe_name(self) -> str:
        """Get the pipe name."""
        return self._channel.pipe_name
